import Foundation

/// Where a patch's sound actually comes from. Shown to the user on every patch
/// so it is always clear what is real sample playback vs. an approximation.
public enum PatchSourceType: String, Codable, CaseIterable, Sendable {
    /// A preset inside an SF2/DLS SoundFont bank.
    case soundFont
    /// Generated by an oscillator/synth engine (not used in Milestone 1).
    case synthesized
    /// A licensed third-party sample pack.
    case licensedSample
    /// Samples the user recorded or imported themselves.
    case userSample
    /// Built from an AI-separated stem. Always labelled experimental.
    case experimentalExtraction

    public var displayName: String {
        switch self {
        case .soundFont: return "SoundFont"
        case .synthesized: return "Synthesized"
        case .licensedSample: return "Licensed sample"
        case .userSample: return "User sample"
        case .experimentalExtraction: return "Experimental extraction"
        }
    }
}

public enum InstrumentFamily: String, Codable, CaseIterable, Sendable {
    case piano, electricPiano, organ, strings, synthStrings, pad, bell, mallet
    case flute, reed, brass, guitar, pluck, synthLead, bass, choir, ethnic, percussion, other

    public var displayName: String {
        switch self {
        case .piano: return "Piano"
        case .electricPiano: return "Electric piano"
        case .organ: return "Organ"
        case .strings: return "Strings"
        case .synthStrings: return "Synth strings"
        case .pad: return "Pad"
        case .bell: return "Bell"
        case .mallet: return "Mallet"
        case .flute: return "Flute"
        case .reed: return "Reed"
        case .brass: return "Brass"
        case .guitar: return "Guitar"
        case .pluck: return "Pluck"
        case .synthLead: return "Synth lead"
        case .bass: return "Bass"
        case .choir: return "Choir"
        case .ethnic: return "Ethnic"
        case .percussion: return "Percussion"
        case .other: return "Other"
        }
    }
}

/// Points at one preset inside a SoundFont/DLS bank file stored in the app's sound library.
public struct SoundFontReference: Codable, Hashable, Sendable {
    /// File name inside the app's SoundFonts directory (not an absolute path,
    /// so backups restore correctly on another device).
    public var fileName: String
    /// General MIDI program number 0...127.
    public var program: UInt8
    /// 0x79 is Apple's default melodic bank MSB; 0x78 is percussion.
    public var bankMSB: UInt8
    public var bankLSB: UInt8

    public static let melodicBankMSB: UInt8 = 0x79
    public static let percussionBankMSB: UInt8 = 0x78

    public init(fileName: String, program: UInt8, bankMSB: UInt8 = SoundFontReference.melodicBankMSB, bankLSB: UInt8 = 0) {
        self.fileName = fileName
        self.program = program
        self.bankMSB = bankMSB
        self.bankLSB = bankLSB
    }
}

/// Reference to a single audio sample file for user/licensed sample patches (Milestone 3+).
public struct SampleZone: Codable, Hashable, Sendable {
    public var fileName: String
    public var rootNote: MIDINote
    public var keyRange: KeyRange
    public var velocityRange: VelocityRange
    public var startFrame: Int
    public var endFrame: Int?
    public var loopStart: Int?
    public var loopEnd: Int?

    public init(fileName: String, rootNote: MIDINote, keyRange: KeyRange, velocityRange: VelocityRange = .full,
                startFrame: Int = 0, endFrame: Int? = nil, loopStart: Int? = nil, loopEnd: Int? = nil) {
        self.fileName = fileName
        self.rootNote = rootNote
        self.keyRange = keyRange
        self.velocityRange = velocityRange
        self.startFrame = startFrame
        self.endFrame = endFrame
        self.loopStart = loopStart
        self.loopEnd = loopEnd
    }
}

public struct Envelope: Codable, Hashable, Sendable {
    /// Seconds.
    public var attack: Double
    public var decay: Double
    /// 0...1 level.
    public var sustain: Double
    public var release: Double

    public init(attack: Double = 0.005, decay: Double = 0.2, sustain: Double = 1.0, release: Double = 0.3) {
        self.attack = attack
        self.decay = decay
        self.sustain = sustain
        self.release = release
    }
}

public struct FilterSettings: Codable, Hashable, Sendable {
    public var enabled: Bool
    /// Hz.
    public var cutoff: Double
    /// dB.
    public var resonance: Double

    /// Filter envelope: how far the filter opens on each note's attack, in octaves above
    /// `cutoff` (0 = static filter). Classic synth brass and plucks.
    public var envAmount: Double
    /// Seconds for the filter envelope to fall back to `cutoff`.
    public var envDecay: Double
    /// Octaves the filter opens for a hard hit vs a soft one (soft notes sound darker, like real brass).
    public var velocityBrightness: Double

    public init(enabled: Bool = false, cutoff: Double = 20_000, resonance: Double = 0,
                envAmount: Double = 0, envDecay: Double = 0.3, velocityBrightness: Double = 0) {
        self.enabled = enabled
        self.cutoff = cutoff
        self.resonance = resonance
        self.envAmount = envAmount
        self.envDecay = envDecay
        self.velocityBrightness = velocityBrightness
    }

    enum CodingKeys: String, CodingKey { case enabled, cutoff, resonance, envAmount, envDecay, velocityBrightness }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        enabled = try c.decode(Bool.self, forKey: .enabled)
        cutoff = try c.decode(Double.self, forKey: .cutoff)
        resonance = try c.decode(Double.self, forKey: .resonance)
        envAmount = try c.decodeIfPresent(Double.self, forKey: .envAmount) ?? 0
        envDecay = try c.decodeIfPresent(Double.self, forKey: .envDecay) ?? 0.3
        velocityBrightness = try c.decodeIfPresent(Double.self, forKey: .velocityBrightness) ?? 0
    }
}

/// Per-layer effect amounts. In ToneEngine these are send levels (0...100) into the shared
/// master reverb / chorus / delay buses; delay time and feedback then come from
/// `MasterEffects`. (`delayTime`/`delayFeedback` here are used by the legacy Apple-sampler engine.)
public struct EffectSettings: Codable, Hashable, Sendable {
    /// 0...100 wet/dry percentage.
    public var reverbMix: Double
    public var delayMix: Double
    /// Seconds.
    public var delayTime: Double
    public var delayFeedback: Double
    /// 0...100 chorus send.
    public var chorusMix: Double
    public var eq: EQSettings
    /// 0...100: controlled saturation for powerful tones (brass stabs, driven leads). 0 = clean.
    public var drive: Double

    public init(reverbMix: Double = 15, delayMix: Double = 0, delayTime: Double = 0.35, delayFeedback: Double = 25,
                chorusMix: Double = 0, eq: EQSettings = EQSettings(), drive: Double = 0) {
        self.reverbMix = reverbMix
        self.delayMix = delayMix
        self.delayTime = delayTime
        self.delayFeedback = delayFeedback
        self.chorusMix = chorusMix
        self.eq = eq
        self.drive = drive
    }

    enum CodingKeys: String, CodingKey { case reverbMix, delayMix, delayTime, delayFeedback, chorusMix, eq, drive }

    /// Fields added in schema v3 decode with defaults so older libraries still load.
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        reverbMix = try c.decode(Double.self, forKey: .reverbMix)
        delayMix = try c.decode(Double.self, forKey: .delayMix)
        delayTime = try c.decode(Double.self, forKey: .delayTime)
        delayFeedback = try c.decode(Double.self, forKey: .delayFeedback)
        chorusMix = try c.decodeIfPresent(Double.self, forKey: .chorusMix) ?? 0
        eq = try c.decodeIfPresent(EQSettings.self, forKey: .eq) ?? EQSettings()
        drive = try c.decodeIfPresent(Double.self, forKey: .drive) ?? 0
    }
}

public struct EQSettings: Codable, Hashable, Sendable {
    public var lowDB: Double
    public var midDB: Double
    public var midFrequency: Double
    public var highDB: Double

    public init(lowDB: Double = 0, midDB: Double = 0, midFrequency: Double = 1200, highDB: Double = 0) {
        self.lowDB = max(-15, min(15, lowDB))
        self.midDB = max(-15, min(15, midDB))
        self.midFrequency = max(200, min(8000, midFrequency))
        self.highDB = max(-15, min(15, highDB))
    }

    public var isFlat: Bool { abs(lowDB) < 0.05 && abs(midDB) < 0.05 && abs(highDB) < 0.05 }
}

/// How a layer responds to playing: mono/legato with glide suits flute and violin leads
/// (slides between notes approximate gamaka-like movement); vibrato adds life to sustained notes.
public struct ExpressionSettings: Codable, Hashable, Sendable {
    public var mono: Bool
    /// Seconds to slide from the previous note (mono only). 0 = no glide.
    public var glideTime: Double
    /// Pitch-bend wheel range in semitones.
    public var bendRange: Double
    /// Vibrato depth in cents (0 = off), rate in Hz, delay before it fades in (s).
    public var vibratoDepth: Double
    public var vibratoRate: Double
    public var vibratoDelay: Double
    /// 0 = every note full volume, 1 = fully velocity-sensitive.
    public var velocitySensitivity: Double

    public init(mono: Bool = false, glideTime: Double = 0, bendRange: Double = 2, vibratoDepth: Double = 0,
                vibratoRate: Double = 5.5, vibratoDelay: Double = 0.35, velocitySensitivity: Double = 1) {
        self.mono = mono
        self.glideTime = max(0, min(2, glideTime))
        self.bendRange = max(0, min(24, bendRange))
        self.vibratoDepth = max(0, min(100, vibratoDepth))
        self.vibratoRate = max(0.5, min(12, vibratoRate))
        self.vibratoDelay = max(0, min(3, vibratoDelay))
        self.velocitySensitivity = max(0, min(1, velocitySensitivity))
    }

    public static let poly = ExpressionSettings()
    public static let expressiveLead = ExpressionSettings(mono: true, glideTime: 0.06, bendRange: 2, vibratoDepth: 18)
}

/// Master bus of a composite tone.
public struct MasterEffects: Codable, Hashable, Sendable {
    public var eq: EQSettings
    /// Return levels 0...1 of the shared effect buses.
    public var reverbLevel: Double
    public var reverbSize: Double
    public var reverbDamping: Double
    public var chorusLevel: Double
    public var delayLevel: Double
    public var delayTime: Double
    /// 0...0.9
    public var delayFeedback: Double

    public init(eq: EQSettings = EQSettings(), reverbLevel: Double = 0.8, reverbSize: Double = 0.6, reverbDamping: Double = 0.5,
                chorusLevel: Double = 0.7, delayLevel: Double = 0.6, delayTime: Double = 0.35, delayFeedback: Double = 0.3) {
        self.eq = eq
        self.reverbLevel = reverbLevel
        self.reverbSize = reverbSize
        self.reverbDamping = reverbDamping
        self.chorusLevel = chorusLevel
        self.delayLevel = delayLevel
        self.delayTime = delayTime
        self.delayFeedback = delayFeedback
    }
}

public struct LicenseInfo: Codable, Hashable, Sendable {
    public var name: String
    public var url: String?
    public var redistributable: Bool
    public var notes: String?

    public init(name: String, url: String? = nil, redistributable: Bool, notes: String? = nil) {
        self.name = name
        self.url = url
        self.redistributable = redistributable
        self.notes = notes
    }

    public static let unknown = LicenseInfo(name: "Unknown — user supplied", redistributable: false,
                                            notes: "Do not share this patch's audio without checking the source license.")
}

/// One playable instrument sound. Layers reference patches by id.
public struct InstrumentPatch: Codable, Hashable, Identifiable, Sendable {
    public var id: UUID
    public var name: String
    public var family: InstrumentFamily
    public var sourceType: PatchSourceType
    public var soundFont: SoundFontReference?
    public var sampleZones: [SampleZone]
    public var envelope: Envelope
    public var filter: FilterSettings
    public var effects: EffectSettings
    public var isFavorite: Bool
    public var license: LicenseInfo
    public var notes: String?
    /// Oscillator definition when `sourceType == .synthesized`.
    public var synth: SynthSettings?
    /// Default playing behaviour (mono/glide/vibrato) — e.g. flute leads glide between notes.
    public var expression: ExpressionSettings?
    /// Free-form descriptors used by tone matching ("breathy", "bright", "bansuri-like").
    public var tags: [String]?

    /// Envelope rule: SoundFont patches use each SoundFont region's own envelope unless a layer
    /// overrides it; user-sample and synth patches use `envelope`.
    public var usesOwnEnvelope: Bool { sourceType != .soundFont }

    public init(id: UUID = UUID(), name: String, family: InstrumentFamily, sourceType: PatchSourceType,
                soundFont: SoundFontReference? = nil, sampleZones: [SampleZone] = [],
                envelope: Envelope = Envelope(), filter: FilterSettings = FilterSettings(),
                effects: EffectSettings = EffectSettings(), isFavorite: Bool = false,
                license: LicenseInfo = .unknown, notes: String? = nil, synth: SynthSettings? = nil,
                expression: ExpressionSettings? = nil, tags: [String]? = nil) {
        self.synth = synth
        self.expression = expression
        self.tags = tags
        self.id = id
        self.name = name
        self.family = family
        self.sourceType = sourceType
        self.soundFont = soundFont
        self.sampleZones = sampleZones
        self.envelope = envelope
        self.filter = filter
        self.effects = effects
        self.isFavorite = isFavorite
        self.license = license
        self.notes = notes
    }
}
